const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let W=innerWidth,H=innerHeight,DPR=1;function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const nations=[{name:'Water Tribe',region:'Southern Water Tribe',element:'Waterbender',emoji:'❄',color:'#67c8d0',skill:['Ice shard','Tidal sweep','Healing mist'],desc:'Find Master Nima beside the frozen harbor.',zone:-700},{name:'Earth Kingdom',region:'Ba Sing Se outskirts',element:'Earthbender',emoji:'⛰',color:'#b8a26b',skill:['Stone fist','Quake','Stone guard'],desc:'The old road leads to a quiet village.',zone:0},{name:'Fire Nation',region:'Ember Island',element:'Firebender',emoji:'🔥',color:'#f1855e',skill:['Fire bolt','Flame ring','Lightning focus'],desc:'Smoke rises beyond the black-rock shore.',zone:700},{name:'Air Nomads',region:'Western Air Temple',element:'Airbender',emoji:'☁',color:'#d2c8a4',skill:['Air blast','Cyclone','Wind veil'],desc:'A high path winds toward the sky temple.',zone:1400}];
const state={started:false,created:false,name:'Wanderer',gender:'Woman',background:'Curious wanderer',nation:0,avatar:false,level:1,xp:0,health:100,energy:78,x: -680,y:80,camX:-680,camY:80,clock:0,weather:0,kills:0,discoveries:0,quests:0,inventory:[['🧥','Traveler’s coat','Clothing'],['🥟','Warm dumplings ×2','Food'],['🧪','Bending tonic','Potion'],['🪵','Driftwood ×3','Material'],['🧭','Old compass','Keepsake'],['📜','Harbor letter','Quest item']],enemies:[],particles:[],keys:{},stick:{x:0,y:0},combat:false,avatarTime:0};
function regionIndex(x){return x<-300?0:x<350?1:x<1050?2:3}function currentNation(){return nations[regionIndex(state.x)]}function project(x,y,z=0){const s=Math.min(W/1000,1.3);return [W/2+(x-state.camX-y+state.camY)*.68*s,H*.54+(x-state.camX+y-state.camY)*.34*s-z*s]}
function rand(a,b){return a+Math.random()*(b-a)}function hash(a,b){let n=Math.sin(a*127.1+b*311.7)*43758.5453;return n-Math.floor(n)}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function ellipse(x,y,rx,ry,c){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=c;ctx.fill()}
function line(x1,y1,x2,y2,c,w=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=c;ctx.lineWidth=w;ctx.lineCap='round';ctx.stroke()}
function drawBackdrop(){const i=regionIndex(state.camX),t=state.clock,sky=ctx.createLinearGradient(0,0,0,H);const palettes=[['#a8c9c7','#efd6b0','#566f70'],['#b8c5a3','#e6d2a0','#53654d'],['#c98e69','#efbf82','#75473e'],['#97b9bd','#e3dcc2','#6e8881']][i];sky.addColorStop(0,palettes[0]);sky.addColorStop(.52,palettes[1]);sky.addColorStop(1,palettes[2]);ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
const night=(Math.sin(t*.015)+1)/2;ctx.fillStyle=`rgba(11,25,40,${Math.max(0,night-.74)*.68})`;ctx.fillRect(0,0,W,H);
// distant layered ranges
for(let layer=0;layer<3;layer++){ctx.beginPath();ctx.moveTo(0,H*.46+layer*34);for(let x=0;x<=W+40;x+=40){const y=H*.37+layer*38+Math.sin(x*.009+layer*4+state.clock*.0004)*27+Math.sin(x*.021+layer)*13;ctx.lineTo(x,y)}ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fillStyle=layer===0?['#728e8b','#879174','#9e6d5b','#9db8b5'][i]:layer===1?['#577675','#6f785b','#805749','#809c98'][i]:['#365e60','#485d4b','#603f38','#647f79'][i];ctx.fill()}
// sun
const sx=W*.78,sy=H*.17;const sun=ctx.createRadialGradient(sx,sy,2,sx,sy,65);sun.addColorStop(0,'#fff3c9cc');sun.addColorStop(1,'#f1cb8490');ctx.fillStyle=sun;ctx.fillRect(sx-65,sy-65,130,130);ellipse(sx,sy,19,19,'#fff1c4');
// textured distant water/ground below horizon
ctx.fillStyle=['#5b9294','#687a51','#82604d','#718e8b'][i];ctx.fillRect(0,H*.5,W,H*.5);
// ground light perspective strips
for(let k=0;k<8;k++){let yy=H*.53+k*k*7;line(0,yy,W,yy,`rgba(238,218,162,${.04+k*.004})`,1)}
}
function groundDiamond(x,y,size,c){const p=project(x,y);const s=Math.min(W/1000,1.3);poly([[p[0],p[1]-size*.29*s],[p[0]+size*.68*s,p[1]],[p[0],p[1]+size*.28*s],[p[0]-size*.68*s,p[1]]],c)}
function drawGroundDetails(){let i=regionIndex(state.camX),baseX=Math.floor((state.camX-750)/160)*160,baseY=Math.floor((state.camY-750)/160)*160;for(let x=baseX;x<state.camX+900;x+=160){for(let y=baseY;y<state.camY+900;y+=160){const h=hash(x,y);groundDiamond(x,y,75,['#73a49b','#8b9868','#a77b5e','#93b3a5'][i]+(h>.5?'':'aa'));if(h>.7){const p=project(x+35,y-30);ctx.save();ctx.translate(p[0],p[1]);ctx.rotate(-.25);line(0,0,10,-4,'#e5d6a177',2);line(5,2,12,0,'#e5d6a177',1);ctx.restore()}}}}
function drawTree(x,y,kind=0){const p=project(x,y),s=Math.min(W/1000,1.3),b=hash(x,y);ellipse(p[0],p[1],19*s,7*s,'#182c2855');if(kind===0){poly([[p[0]-3*s,p[1]],[p[0]+4*s,p[1]],[p[0]+3*s,p[1]-40*s],[p[0]-2*s,p[1]-40*s]],'#655341');for(let j=0;j<3;j++){const yy=p[1]-(30+j*13)*s,rx=(20-j*4)*s;ellipse(p[0]+(b-.5)*8*s,yy,rx,14*s,['#597657','#668568','#75926e'][j])}}else{poly([[p[0]-2*s,p[1]],[p[0]+4*s,p[1]],[p[0]+3*s,p[1]-35*s],[p[0]-2*s,p[1]-35*s]],'#665542');ellipse(p[0],p[1]-42*s,18*s,10*s,'#bc9a6e');ellipse(p[0]-11*s,p[1]-38*s,9*s,12*s,'#c7aa7a');ellipse(p[0]+10*s,p[1]-38*s,9*s,12*s,'#d1ae78')}}
function drawBuilding(x,y,type=0,scale=1){const p=project(x,y),s=Math.min(W/1000,1.3)*scale;ellipse(p[0],p[1]+2*s,42*s,13*s,'#14231f5c');let col=type===0?['#b6d2c6','#c9a477','#a65848','#e0d1a0']:['#8bb2b4','#b99b6f','#914c3f','#c6bd9f'];poly([[p[0]-30*s,p[1]-38*s],[p[0]+22*s,p[1]-38*s],[p[0]+22*s,p[1]],[p[0]-30*s,p[1]]],col[0]);poly([[p[0]+22*s,p[1]-38*s],[p[0]+38*s,p[1]-28*s],[p[0]+38*s,p[1]+4*s],[p[0]+22*s,p[1]]],col[1]);poly([[p[0]-36*s,p[1]-39*s],[p[0]-4*s,p[1]-60*s],[p[0]+28*s,p[1]-39*s]],col[2]);poly([[p[0]-38*s,p[1]-39*s],[p[0]-4*s,p[1]-63*s],[p[0]+31*s,p[1]-39*s],[p[0]+25*s,p[1]-36*s],[p[0]-4*s,p[1]-56*s],[p[0]-33*s,p[1]-35*s]],'#e5c986');poly([[p[0]-9*s,p[1]-24*s],[p[0]+2*s,p[1]-24*s],[p[0]+2*s,p[1]],[p[0]-9*s,p[1]]],'#493b34');ellipse(p[0]+10*s,p[1]-25*s,4*s,5*s,'#f3d48b')}
function drawLandmark(){const idx=regionIndex(state.camX);const lx=nations[idx].zone,lp=project(lx,20,-1);if(idx===0){drawBuilding(lx+80,-60,0,1.45);drawBuilding(lx+165,65,0,.8);for(let n=0;n<6;n++)drawTree(lx-100+n*46,-80+hash(n,1)*90,1);line(lp[0]-40,lp[1]+13,lp[0]+50,lp[1]+13,'#d8c49a',4)}else if(idx===1){drawBuilding(lx+65,10,1,1.5);drawBuilding(lx+160,-80,1,.75);for(let n=0;n<6;n++)drawTree(lx-115+n*47,80+hash(n,4)*90,0)}else if(idx===2){drawBuilding(lx+60,10,1,1.4);drawBuilding(lx+160,-100,1,.8);for(let n=0;n<7;n++){const q=project(lx-180+n*57,-120);ellipse(q[0],q[1]-5,20,7,'#3e2525');ellipse(q[0]+6,q[1]-18,8,19,'#aa6549aa')}}else{drawBuilding(lx+75,10,0,1.38);drawBuilding(lx+170,-110,0,.75);for(let n=0;n<7;n++)drawTree(lx-150+n*50,110+hash(n,3)*50,1);const p=project(lx-60,-30);line(p[0],p[1]-14,p[0]+7,p[1]-52,'#d8d1b2',3);ellipse(p[0]+7,p[1]-54,13,9,'#e2dbc2')}
}
function drawNPC(x,y,name,robe='#d6c69b',master=false){const p=project(x,y),s=Math.min(W/1000,1.3),bob=Math.sin(state.clock*.003+x)*1.5;ellipse(p[0],p[1]+2,9*s,4*s,'#14231f55');poly([[p[0]-6*s,p[1]-19*s+bob],[p[0]+6*s,p[1]-19*s+bob],[p[0]+9*s,p[1]-3*s],[p[0]-9*s,p[1]-3*s]],robe);ellipse(p[0],p[1]-23*s+bob,5*s,5*s,'#d6a982');if(master)line(p[0],p[1]-7*s,p[0],p[1]-17*s,'#e7c77f',2);if(Math.hypot(x-state.x,y-state.y)<115){ctx.font=`${10*s}px sans-serif`;ctx.textAlign='center';ctx.fillStyle='#ffedc5';ctx.shadowColor='#000';ctx.shadowBlur=5;ctx.fillText(name,p[0],p[1]-36*s);ctx.shadowBlur=0}}
function drawPlayer(){const p=project(state.x,state.y),s=Math.min(W/1000,1.3),bob=Math.sin(state.clock*.012)*(Math.hypot(state.keys.dx||0,state.keys.dy||0)>.1?2:0);ellipse(p[0],p[1]+3,15*s,6*s,'#11231f77');let robe=['#3c727a','#7f6d48','#9c4f3d','#ded1ac'][regionIndex(state.x)];if(state.avatarTime>0){ctx.shadowColor='#b8f5ff';ctx.shadowBlur=25;robe='#e8dfb8'}poly([[p[0]-9*s,p[1]-28*s+bob],[p[0]+9*s,p[1]-28*s+bob],[p[0]+12*s,p[1]-3*s],[p[0]-12*s,p[1]-3*s]],robe);poly([[p[0]-8*s,p[1]-28*s+bob],[p[0],p[1]-24*s+bob],[p[0]+8*s,p[1]-28*s+bob],[p[0]+4*s,p[1]-4*s],[p[0]-4*s,p[1]-4*s]],'#d5ba7b');ellipse(p[0],p[1]-35*s+bob,7*s,7*s,'#d6a47e');ellipse(p[0],p[1]-37*s+bob,7*s,4*s,['#263d3d','#453527','#382523','#574d42'][regionIndex(state.x)]);line(p[0]-7*s,p[1]-20*s,p[0]-13*s,p[1]-11*s,'#d6a47e',3*s);line(p[0]+7*s,p[1]-20*s,p[0]+13*s,p[1]-11*s,'#d6a47e',3*s);line(p[0]-4*s,p[1]-4*s,p[0]-5*s,p[1]+2*s,'#483d34',3*s);line(p[0]+4*s,p[1]-4*s,p[0]+5*s,p[1]+2*s,'#483d34',3*s);if(state.avatarTime>0)ctx.shadowBlur=0;if(Math.hypot(state.x-30,state.y)<22){ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillStyle='#fff0c8';ctx.fillText(state.name,p[0],p[1]-49*s)}}

function drawEnemies(){for(const e of state.enemies){if(e.dead)continue;const p=project(e.x,e.y),s=Math.min(W/1000,1.3);ellipse(p[0],p[1]+2,12*s,5*s,'#17221d77');poly([[p[0]-8*s,p[1]-22*s],[p[0]+8*s,p[1]-22*s],[p[0]+11*s,p[1]-3*s],[p[0]-11*s,p[1]-3*s]],e.color);ellipse(p[0],p[1]-26*s,7*s,7*s,'#a87a5e');line(p[0]-6*s,p[1]-18*s,p[0]-14*s,p[1]-8*s,e.color,3*s);ctx.fillStyle='#111';ctx.fillRect(p[0]-12*s,p[1]-35*s,24*s,3*s);ctx.fillStyle='#e65d50';ctx.fillRect(p[0]-12*s,p[1]-35*s,24*s*Math.max(0,e.hp/e.max),3*s);if(e.hit>0){ctx.strokeStyle=`rgba(255,230,150,${e.hit/12})`;ctx.lineWidth=3;ctx.beginPath();ctx.arc(p[0],p[1]-16*s,20*s,0,Math.PI*2);ctx.stroke();e.hit--}}}
function drawParticles(){for(const p of state.particles){let q=project(p.x,p.y,-p.z);ctx.globalAlpha=Math.max(0,p.life/p.max);if(p.type==='text'){ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillStyle=p.color;ctx.fillText(p.text,q[0],q[1])}else{ctx.fillStyle=p.color;ellipse(q[0],q[1],p.size,p.size,p.color)}ctx.globalAlpha=1;p.x+=p.vx;p.y+=p.vy;p.z+=p.vz;p.life--;p.size*=.985}state.particles=state.particles.filter(p=>p.life>0)}
function drawWind(){const i=regionIndex(state.camX),col=['#a4d8dd55','#c1cf8e55','#ffb27855','#edf0d888'][i];for(let n=0;n<10;n++){const x=((n*137+state.clock*.27)%(W+60))-30,y=(n*89+Math.sin(state.clock*.003+n)*13)%H;line(x,y,x+18+Math.sin(n)*20,y-5,col,1)}}
function render(){state.clock++;state.camX+=(state.x-state.camX)*.085;state.camY+=(state.y-state.camY)*.085;drawBackdrop();drawGroundDetails();drawWind();drawLandmark();const i=regionIndex(state.x);let masterX=nations[i].zone+120;drawNPC(masterX,55,['Master Nima','Old Tashi','Captain Raku','Sister Lian'][i],['#d8e6e2','#8f8962','#ad5e48','#e1d8b8'][i],true);drawNPC(masterX+110,-55,['Mira','Jin','Hoku','Pema'][i],['#d7c19a','#b99764','#d06c4b','#cfc4a2'][i],false);drawEnemies();drawPlayer();drawParticles();requestAnimationFrame(render)}requestAnimationFrame(render);
function addParticle(x,y,color,opts={}){state.particles.push({x,y,z:opts.z||0,vx:opts.vx??rand(-1.5,1.5),vy:opts.vy??rand(-1.5,1.5),vz:opts.vz??rand(.2,2),life:opts.life||35,max:opts.life||35,size:opts.size||rand(2,5),color,type:opts.type||'dot',text:opts.text})}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2200)}
function setHUD(){const n=currentNation();$('#hudName').textContent=state.name;$('#elementName').textContent=state.avatar?'Avatar':state.nation===regionIndex(state.x)?n.element:nations[state.nation].element;$('#elementEmoji').textContent=state.avatar?'✧':nations[state.nation].emoji;$('#regionName').textContent=n.region;$('#healthFill').style.width=state.health+'%';$('#energyFill').style.width=state.energy+'%';$('#healthText').textContent=Math.round(state.health);$('#energyText').textContent=Math.round(state.energy);$('#levelText').textContent=String(state.level).padStart(2,'0');$('#xpText').textContent=`${state.xp} / ${state.level*100} XP`;$('#xpFill').style.width=(state.xp/(state.level*100)*100)+'%';const sk=nations[state.nation].skill;$('#skillOne').innerHTML=`${state.nation===0?'❄':state.nation===1?'◈':state.nation===2?'🔥':'〰'}<small>1</small>`;$('#skillTwo').innerHTML=`${state.nation===0?'〰':state.nation===1?'⛰':state.nation===2?'✹':'◎'}<small>2</small>`;$('#skillThree').innerHTML=`${state.nation===0?'✧':state.nation===1?'⬟':state.nation===2?'⚡':'◌'}<small>3</small>`;$('#skillMobile').textContent=state.nation===0?'❄':state.nation===1?'◈':state.nation===2?'🔥':'〰';$('#questDesc').textContent=state.quests===0?nations[0].desc:state.quests===1?'Speak with a local master and learn the first form.':state.quests===2?'Follow the old road and find the next nation.':'The world is yours to explore. Find balance in your own way.';$('#questName').textContent=state.quests===0?'A call from the coast':state.quests===1?'Lessons in balance':state.quests===2?'Beyond the horizon':'The long way home';$('#questCount').textContent=state.quests===0?'Explore the coast':state.quests===1?'Meet a bending master':state.quests===2?'Discover a new nation':'Journey on';$('#combatPrompt').textContent=nearMaster()?'E / tap the master to speak':''}
function earnXP(amount,reason){state.xp+=amount;toast(`+${amount} XP · ${reason}`);while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.health=100;state.energy=100;toast(`Level ${state.level} reached · New strength awakens!`)}setHUD()}
function nearbyEnemy(){return state.enemies.find(e=>!e.dead&&Math.hypot(e.x-state.x,e.y-state.y)<100)}
function spawnEnemy(){const x=state.x+rand(250,440)*(Math.random()<.5?-1:1),y=state.y+rand(-180,180);state.enemies.push({x,y,hp:3,max:3,dead:false,hit:0,color:['#786147','#66483e','#59624c'][Math.floor(Math.random()*3)],cool:0})}
for(let i=0;i<5;i++)spawnEnemy();
function attack(power=1,elemental=false){if(!state.created)return;const e=nearbyEnemy();const nation=nations[state.nation];if(elemental){if(state.energy<12){toast('Not enough energy');return}state.energy=Math.max(0,state.energy-(power===3?24:12))}if(e){e.hp-=power;e.hit=12;state.combat=true;for(let i=0;i<8;i++){const col=elemental?nation.color:'#efc37a';addParticle(e.x,e.y,col,{z:rand(0,35),life:rand(16,35),size:rand(2,6)})}if(e.hp<=0){e.dead=true;state.kills++;state.inventory[3][1]='Driftwood ×'+(3+state.kills);earnXP(40,'foe defeated');setTimeout(spawnEnemy,1800)}}else if(elemental){for(let i=0;i<12;i++)addParticle(state.x+rand(-48,48),state.y+rand(-30,30),nation.color,{z:rand(0,40),life:rand(18,36),size:rand(3,8)});toast(nation.skill[power===3?2:power===2?1:0])}else toast('No foe in reach');state.energy=Math.min(100,state.energy+0);setHUD()}
function skill(n){if(n===3){if(state.energy<18){toast('Not enough energy');return}state.energy-=18;if(state.health<100){state.health=Math.min(100,state.health+27);toast(state.nation===0?'Healing waters restore your strength':'You steady your breathing and recover')}else{for(let k=0;k<14;k++)addParticle(state.x+rand(-30,30),state.y+rand(-30,30),state.avatar?'#e1d995':nations[state.nation].color,{z:rand(5,60),life:35});toast(state.avatar?'Avatar State · balance awakens':'A defensive stance surrounds you')}if(state.avatar)state.avatarTime=220;setHUD();return}attack(n===2?2:1,true)}
function dodge(){let dx=state.keys.dx||state.stick.x,dy=state.keys.dy||state.stick.y;if(Math.hypot(dx,dy)<.1)dx=1;state.x+=dx*75;state.y+=dy*75;for(let k=0;k<9;k++)addParticle(state.x+rand(-12,12),state.y+rand(-12,12),'#d8e6d0',{z:rand(0,28),life:28,size:3});toast('Quick step')}
function interact(){const i=regionIndex(state.x),mx=nations[i].zone+120;if(Math.hypot(state.x-mx,state.y-55)<145){if(state.quests===0){state.quests=1;earnXP(30,'master discovered');toast('Master Nima: “The first lesson is to listen.”')}else if(state.avatar&&state.nation!==i){state.nation=i;state.inventory.push(['📜',`${nations[i].element} lesson`,'Technique']);state.quests=Math.min(3,state.quests+1);earnXP(80,`${nations[i].element} learned`);toast(`You learned ${nations[i].element}!`)}else{state.quests=Math.min(3,state.quests+1);earnXP(20,'training completed');toast('A useful lesson for the road ahead.')}setHUD()}else toast('Come closer to a local master')}
function discover(){const idx=regionIndex(state.x);if(!state.discovered)state.discovered={};if(!state.discovered[idx]){state.discovered[idx]=true;state.discoveries++;earnXP(50,'new region discovered');toast(`Discovered ${nations[idx].region}`);if(idx!==state.nation&&state.avatar&&state.quests<3){state.nation=idx;toast(`${nations[idx].element} masters may teach you here`)}}}
let lastRegion=-1;function update(){if(!state.created)return;const k=state.keys,dx=(k.right?1:0)-(k.left?1:0)+(state.stick.x||0),dy=(k.down?1:0)-(k.up?1:0)+(state.stick.y||0),len=Math.hypot(dx,dy);k.dx=dx;k.dy=dy;if(len>.1){state.x+=dx/Math.max(1,len)*3.1;state.y+=dy/Math.max(1,len)*3.1;if(Math.random()<.07)addParticle(state.x+rand(-8,8),state.y+rand(-8,8),'#efe3c074',{z:0,life:18,size:2})}const ri=regionIndex(state.x);if(ri!==lastRegion){lastRegion=ri;setHUD();if(ri!==state.nation)discover()}state.energy=Math.min(100,state.energy+.08);if(state.avatarTime>0)state.avatarTime--;for(const e of state.enemies){if(e.dead)continue;let d=Math.hypot(state.x-e.x,state.y-e.y);if(d<235){e.x+=(state.x-e.x)/Math.max(d,1)*.52;e.y+=(state.y-e.y)/Math.max(d,1)*.52;if(d<20&&e.cool<=0){state.health=Math.max(0,state.health-6);e.cool=70;setHUD();if(state.health===0){state.health=100;state.x=-680;state.y=80;toast('You awaken at the harbor, safe but humbled.')}}}if(e.cool>0)e.cool--}}
