 $('#inventoryBtn').onclick=$('#inventoryTopBtn').onclick=()=>{renderInventory();openOverlay('#inventoryOverlay')};$('#mapBtn').onclick=()=>openOverlay('#mapOverlay');$('#journalBtn').onclick=()=>openOverlay('#journalOverlay');$$('[data-close]').forEach(x=>x.onclick=()=>closeOverlay(x.dataset.close));$$('.overlay').forEach(x=>x.onclick=e=>{if(e.target===x)x.classList.remove('show')});
 function renderInventory(){$('#inventoryGrid').innerHTML=state.inventory.map(x=>`<div class="item"><span class="item-icon">${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}

